import re


def run(annotation: str, sentence: dict) -> str:
    """Write clock times as zero-padded nodes: ':time 5h30m' -> ':time (sNh1 / 05h30m)'; '/ 0h15m' -> '/ 00h15m'."""
    i1 = annotation.find('# alignment:')
    if i1 < 0:
        return annotation
    g, rest = annotation[:i1], annotation[i1:]
    m = re.search(r'\((s\d+)s0\s*/', rest)
    prefix = m.group(1) if m else 's%s' % sentence.get('index', 0)
    used = set(re.findall(r'\(\s*([^\s()]+)\s*/', g))
    counter = [0]

    def pad(h, mi):
        return '%02dh%02dm' % (int(h), int(mi))

    def newvar():
        while True:
            counter[0] += 1
            v = '%sh%d' % (prefix, counter[0])
            if v not in used:
                used.add(v)
                return v

    def repl(mm):
        return '%s(%s / %s)' % (mm.group(1), newvar(), pad(mm.group(2), mm.group(3)))

    g = re.sub(r'(:time\s+)(\d{1,2})h(\d{1,2})m(?=[\s)])', repl, g)
    g = re.sub(r'(/\s*)(\d{1,2})h(\d{1,2})m(?=[\s)])', lambda mm: mm.group(1) + pad(mm.group(2), mm.group(3)), g)
    return g + rest

import re


def run(annotation: str, sentence: dict) -> str:
    """If the document-level modal says (author :full-negative v) and v has no :polarity in the graph, add ':polarity -' to v."""
    i1 = annotation.find('# alignment:')
    i2 = annotation.find('# document level annotation:')
    if i1 < 0 or i2 < i1:
        return annotation
    g, rest = annotation[:i1], annotation[i1:]
    doc = annotation[i2:]
    negs = re.findall(r'\(\s*author\s+:full-negative\s+([^\s()]+)\s*\)', doc)
    for v in negs:
        m = re.search(r'\(\s*' + re.escape(v) + r'\s*/\s*([^\s()]+)', g)
        if not m:
            continue
        depth = 0
        has = False
        end = None
        for k in range(m.start(), len(g)):
            c = g[k]
            if c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
                if depth == 0:
                    end = k
                    break
            elif c == ':' and depth == 1 and g.startswith(':polarity', k):
                has = True
        if end is None or has:
            continue
        g = g[:m.end()] + ' :polarity -' + g[m.end():]
    return g + rest

