import resources


def roleset_lookup(lemma: str) -> str:
    """Look up English PropBank rolesets for a lemma (verb, adjective or noun base form, e.g. 'dump', 'full', 'important', 'get'). Returns lines like 'dump-01  ARG0: ...  ARG1: ...' with all senses and their numbered roles, so you can pick the sense number and ARG roles. Returns 'no roleset' if the lemma has none (then use -01 for verbs, or a plain lemma / abstract predicate)."""
    lem = lemma.strip().lower().replace(' ', '-').replace('_', '-')
    if not lem:
        return 'no roleset: empty lemma'
    try:
        text = resources.read_resource('propbank-en-args.txt')
    except Exception:
        return 'lookup unavailable'
    out = [ln for ln in text.splitlines() if ln.startswith(lem + '-')]
    if not out:
        return 'no roleset for ' + lem
    return '\n'.join(out[:14])

import re

MODMAP = {
    'fullaff': 'full-affirmative', 'full-aff': 'full-affirmative', 'full-affirmative': 'full-affirmative', 'fullaffirmative': 'full-affirmative',
    'prtaff': 'partial-affirmative', 'prt-aff': 'partial-affirmative', 'partaff': 'partial-affirmative', 'partial-affirmative': 'partial-affirmative',
    'neutaff': 'neutral-affirmative', 'neut-aff': 'neutral-affirmative', 'neutral-affirmative': 'neutral-affirmative',
    'fullneg': 'full-negative', 'full-neg': 'full-negative', 'full-negative': 'full-negative',
    'prtneg': 'partial-negative', 'prt-neg': 'partial-negative', 'partneg': 'partial-negative', 'partial-negative': 'partial-negative',
    'neutneg': 'neutral-negative', 'neut-neg': 'neutral-negative', 'neutral-negative': 'neutral-negative',
    'unsp': 'unspecified', 'unspecified': 'unspecified',
}
GENERIC = ('str', 'strength', 'modstr', 'modal-strength', 'mod')
BANNED = ('DCT', 'ROOT', 'PAST_REF', 'PRESENT_REF', 'FUTURE_REF')
TUP = re.compile(r'\(\s*([^\s()]+)\s+(:[^\s()]+)\s+([^\s()]+)\s*\)')


def match_close(s, i):
    d = 0
    inq = False
    for j in range(i, len(s)):
        c = s[j]
        if c == '"':
            inq = not inq
        elif not inq:
            if c == '(':
                d += 1
            elif c == ')':
                d -= 1
                if d == 0:
                    return j
    return -1


def modstr_of(graph, var):
    m = re.search(r'\(' + re.escape(var) + r'\s*/', graph)
    if not m:
        return ''
    end = match_close(graph, m.start())
    if end < 0:
        end = len(graph) - 1
    node = graph[m.start():end + 1]
    for t in re.finditer(r':modstr\s+([\w-]+)', node):
        pre = node[:t.start()]
        if pre.count('(') - pre.count(')') == 1:
            return t.group(1)
    return ''


def group_span(doc, name):
    k = doc.find(':' + name + ' ')
    if k < 0:
        k = doc.find(':' + name + '(')
    if k < 0:
        return None
    p = doc.find('(', k)
    if p < 0:
        return None
    e = match_close(doc, p)
    if e < 0:
        return None
    return k, p, e


def fix_doc(doc, graph):
    def fix_tuple(m):
        a, rel, b = m.group(1), m.group(2), m.group(3)
        key = rel.lstrip(':').lower().replace('_', '-')
        if a.upper() == 'AUTH':
            a = 'author'
        if key in MODMAP:
            lab = MODMAP[key]
        elif key in GENERIC:
            lab = MODMAP.get(modstr_of(graph, b).lower(), 'full-affirmative')
        else:
            return '(%s %s %s)' % (a, rel, b)
        return '(%s :%s %s)' % (a, lab, b)

    sp = group_span(doc, 'temporal')
    if sp:
        k, p, e = sp
        body = doc[p:e + 1]

        def drop(m):
            if m.group(1) in BANNED or m.group(3) in BANNED:
                return ''
            return m.group(0)

        nb = TUP.sub(drop, body)
        if not TUP.search(nb):
            st = k
            while st > 0 and doc[st - 1] in ' \t':
                st -= 1
            en = e + 1
            if en < len(doc) and doc[en] == '\n':
                en += 1
            doc = doc[:st] + doc[en:]
        else:
            doc = doc[:p] + nb + doc[e + 1:]
    sp = group_span(doc, 'modal')
    if sp:
        k, p, e = sp
        body = TUP.sub(fix_tuple, doc[p:e + 1])
        if '(root :modal author)' not in body:
            body = '(' + '(root :modal author)\n               ' + body[1:]
        doc = doc[:p] + body + doc[e + 1:]
    return doc


def fix_graph(g):
    g = g.replace(':ref-person', ':refer-person').replace(':ref-number', ':refer-number')
    g = re.sub(r'(:refer-number\s+)([\w-]+)', lambda m: m.group(1) + m.group(2).lower(), g)
    g = re.sub(r'(:aspect\s+)([\w-]+)', lambda m: m.group(1) + m.group(2).lower(), g)
    g = re.sub(r':modpred\s+(s\d+[a-z]\d*)(?=[\s)])', r':modal-predicate \1', g)
    g = re.sub(r'[ \t]*:modstr\s+[\w-]+', '', g)
    g = re.sub(r'\n[ \t]*\n(?=[ \t]*:)', '\n', g)
    return g


def run(annotation: str, sentence: dict) -> str:
    h1 = '# sentence level graph:'
    h2 = '# alignment:'
    h3 = '# document level annotation:'
    i1 = annotation.find(h1)
    i2 = annotation.find(h2)
    i3 = annotation.find(h3)
    if i1 < 0 or i2 < 0 or i3 < 0 or not (i1 < i2 < i3):
        return annotation
    head = annotation[:i1]
    graph = annotation[i1 + len(h1):i2]
    align = annotation[i2:i3]
    doc = annotation[i3 + len(h3):]
    doc = fix_doc(doc, graph)
    graph = fix_graph(graph)
    return head + h1 + graph + align + h3 + doc

