import resources


def roleset_lookup(lemma: str) -> str:
    """Look up English PropBank rolesets for a lemma (verb, adjective or noun base form, e.g. 'dump', 'full', 'important', 'get'). Returns lines like 'dump-01  ARG0: ...  ARG1: ...' with all senses and their numbered roles, so you can pick the sense number and ARG roles. Returns 'no roleset' if the lemma has none (then use -01 for verbs, or a plain lemma / abstract predicate)."""
    lem = lemma.strip().lower().replace(' ', '-').replace('_', '-')
    if not lem:
        return 'no roleset: empty lemma'
    try:
        text = resources.read_resource('propbank-en-args.txt')
    except Exception:
        return 'lookup unavailable'
    out = [ln for ln in text.splitlines() if ln.startswith(lem + '-')]
    if not out:
        return 'no roleset for ' + lem
    return '\n'.join(out[:14])

