def variants(lem: str) -> list:
    out = [lem]
    rules = (('ers', ['e', '']), ('er', ['e', '']), ('ors', ['e', '']), ('or', ['e', '']),
             ('ions', ['e', '']), ('ion', ['e', '']), ('ing', ['e', '']), ('ed', ['e', '']),
             ('ies', ['y']), ('s', ['']))
    for suf, reps in rules:
        if lem.endswith(suf) and len(lem) > len(suf) + 2:
            for r in reps:
                c = lem[:-len(suf)] + r
                if c not in out:
