import re

TAGRE = re.compile(r'(<(EVENT|TIMEX3)\b[^>]*>)(.*?)</\2>', re.S)


def strip_tags(s):
    return re.sub(r'<[^>]+>', '', s)


def run(annotation: str, sentence: dict) -> str:
    text = sentence.get('text', '')
    lines = annotation.split('\n')
    tl = []
    body = []
    for ln in lines:
        s = ln.strip()
        if s.startswith('<TLINK'):
            if s not in tl:
                tl.append(s)
        else:
            body.append(ln)
    btxt = '\n'.join(body).strip()
    if strip_tags(btxt).strip() == text:
        out = btxt
    else:
        out = ''
        cur = 0
        for m in TAGRE.finditer(btxt):
            inner = strip_tags(m.group(3))
            idx = text.find(inner, cur)
            if idx < 0 or not inner:
                continue
            out += text[cur:idx] + m.group(1) + inner + '</' + m.group(2) + '>'
            cur = idx + len(inner)
        out += text[cur:]
    if tl:
        out += '\n' + '\n'.join(tl)
    return out

tests:
s = {'index': 1, 'text': 'He left Monday.'}
a = 'He <EVENT eid="e1_1" class="OCCURRENCE">left</EVENT> Monday.\n<TLINK eventID="e1_1" relatedToTime="t0" relType="BEFORE"/>'
assert run(a, s) == a

